const pmv = key => { const p = S.ops[key]; if (!p) return [null, null, null]; if (!Array.isArray(p.mv)) p.mv = defaultMoves(key, p.lvl); return p.mv; };
// IV rank 1–6 (raised by catching duplicates); shown as IVs on the summary screen
