const PRI_ATK = () => PRI_ATK.v || (PRI_ATK.v = Object.keys(MOVES).filter(m => MOVES[m].pri > 0 && MOVES[m].c !== "X" && MOVES[m].p > 0 && m !== "fakeout"));
